{
  "findings": [
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent reports that voice chat is off for all users under 13 and can be turned on only for trusted friends for ages 9-12.",
      "stance": "risk",
      "quote": "Voice Chat with friends is OFF for all users under 13. Parents can choose enable voice chat with trusted friends for users 9-12."
    },
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent reports that text and voice chat may be disabled in some countries and video chat is not available anywhere.",
      "stance": "risk",
      "quote": "Please be aware that Text and/or Voice Chat may be disabled in your country. Video Chat is not available in any location."
    },
    {
      "ref": "[D536]",
      "area": "money",
      "claim": "A parent reports that spending limits can be set and notifications are sent for high spend alerts.",
      "stance": "mitigation",
      "quote": "Set a Monthly spending limit. ... You can also determine if you want to receive spending notifications. You can choose if you want to be notified for all transactions, high spend alerts, or none. High spend notifications are on by default for all linked parents. This means that you should receive purchase notifications after $100, $250, and $500 of spend in a given month."
    },
    {
      "ref": "[D536]",
      "area": "data",
      "claim": "A parent reports that the platform collects age verification data via government-issued ID or credit card and shares it for verification.",
      "stance": "risk",
      "quote": "Follow the onscreen steps to verify your age using a government-issued ID or credit card. Learn more about Age ID verification."
    },
    {
      "ref": "[D536]",
      "area": "age_gating",
      "claim": "A parent reports that age gating requires ID or credit card verification and unlocks default age group settings.",
      "stance": "mitigation",
      "quote": "This will unlock [default age group settings](https://about.roblox.com/safety-by-age). You can adjust these settings by following the instructions below."
    },
    {
      "ref": "[D536]",
      "area": "content",
      "claim": "A parent reports that experiences with sensitive issues can be blocked by default for users under 13.",
      "stance": "risk",
      "quote": "By default, users under 13 cannot access experiences that are primarily themed on sensitive issues."
    },
    {
      "ref": "[D536]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data collection and child safety failures.",
      "stance": "risk",
      "quote": "Roblox has been fined by the FTC for violating COPPA and for inadequate age verification, and has settled lawsuits over data collection and chat safety failures."
    }
  ]
}
